    "summary": "يتكون جهاز الغدد الصماء من غدد تفرز الهرمونات مباشرة في مجرى الدم لتؤثر في سلوك الإنسان، وتعد الغدة النخامية 'سيدة الغدد' لإشرافها على الغدد الأخرى وإفرازها لهرمون النمو وهرمون الأكسيتوسين المرتبط بالروابط الاجتماعية والأمومة. وتعمل الغدة الصنوبرية عبر هرمون الميلاتونين على تنظيم دورة النوم والاستيقاظ بناءً على الضوء، في حين تتحكم الغدة الدرقية في عمليات الأيض، حيث يؤدي فرط نشاطها إلى التوتر والنحافة، بينما يسبب خمولها التبلد والسمنة والاكتئاب.\n\nتفرز الغدد الكظرية هرمونات تنظم الأملاح وتساعد على مواجهة الضغوط النفسية، بينما تفرز الغدد الجنسية هرمونات التستوستيرون والأستروجين والبروجسترون لتحديد الفروق السلوكية والجسدية بين الجنسين. وتظهر الأبحاث علاقة تبادلية بين الهرمونات والانفعالات، كما تربط الدراسات العصبية بين حدوث خلل في الدماغ الأمامي (الفص الجبهي) وزيادة خطر السلوك الإجرامي نتيجة تأثر القدرة على السيطرة على الانفعالات واتخاذ القرارات.",
    "keyPoints": [
      "جهاز الغدد الصماء يفرز هرمونات تؤثر في الأنشطة الداخلية والسلوك الظاهر للإنسان بعلاقة تبادلية مع الحالة الانفعالية.",
      "الغدة النخامية تفرز هرمون النمو المسؤول عن الطول وهرمون الأكسيتوسين المسؤول عن الروابط الاجتماعية والأمومة.",
      "الغدة الصنوبرية تفرز هرمون الميلاتونين لتنظيم عمليات النوم والصحو ويتأثر إفرازه بالضوء.",
      "الغدة الدرقية تنظم الأيض، ويؤثر نشاطها أو خمولها بشكل كبير على سمات الشخصية كالعصبية أو التبلد والاكتئاب.",
      "الغدد الكظرية والجنسية تفرز هرمونات تنظم الأملاح، وتساعد في مواجهة الضغوط، وتحدد الفروق السلوكية والجسدية بين الجنسين.",
      "الخلل في مناطق معينة من الدماغ الأمامي يرتبط بضعف السيطرة على الانفعالات وزيادة خطر السلوك الإجرامي."
    ],
