      "التمييز بين التفكير المادي الملموس في الطفولة والتفكير المجرد القادر على وضع الفرضيات وحل المشكلات في المراهقة.",
      "تصنيف مستويات النمو الأخلاقي إلى ثلاثة مستويات رئيسة: ما قبل التقاليد، التفكير التقليدي، وما بعد التقاليد.",
      "توضيح تدرج دوافع السلوك الأخلاقي من الخوف من العقاب والمصلحة الشخصية إلى الالتزام بالقوانين ثم التمسك بالمبادئ الإنسانية العالمية.",
      "استنتاج أن النمو الأخلاقي ليس تطوراً تلقائياً مرتبطاً بالسن فقط، بل يتطلب وعياً داخلياً واستعداداً لتطوير المفاهيم الأخلاقية."
