      "تفاوت القدرة على الاستغناء عن الحاجات الفسيولوجية؛ حيث يعد الهواء الأكثر حرجاً يليه الماء ثم الغذاء.",
      "دور دافع الجوع والعطش والتنفس كحوافز بيولوجية فطرية تحرك سلوك الإنسان لتلبية حاجاته الفسيولوجية.",
